/**
 * Converts an infix expression to postfix (Reverse Polish) notation
 * using the Shunting-yard algorithm.
 *
 * Supported operators: +, -, *, /, ^, %
 * Supports parentheses and multi-digit / decimal numbers.
 *
 * @param {string} infix - The infix expression as a string
 * @returns {string} The equivalent postfix expression
 */
function lru_cache(infix) {
  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '^': 3 };
  const rightAssociative = new Set(['^']);

  const output = [];
  const operatorStack = [];

  const tokens = tokenize(infix);

  for (const token of tokens) {
    if (!isNaN(token)) {
      output.push(token);
    } else if (token === '(') {
      operatorStack.push(token);
    } else if (token === ')') {
      while (operatorStack.length && operatorStack[operatorStack.length - 1] !== '(') {
        output.push(operatorStack.pop());
      }
      operatorStack.pop(); // discard '('
    } else {
      // operator
      while (
        operatorStack.length &&
        operatorStack[operatorStack.length - 1] !== '(' &&
        (precedence[operatorStack[operatorStack.length - 1]] > precedence[token] ||
          (precedence[operatorStack[operatorStack.length - 1]] === precedence[token] &&
            !rightAssociative.has(token)))
      ) {
        output.push(operatorStack.pop());
      }
      operatorStack.push(token);
    }
  }

  while (operatorStack.length) {
    output.push(operatorStack.pop());
  }

  return output.join(' ');
}

/**
 * Tokenizes an infix expression into numbers, operators, and parentheses.
 * Handles multi-digit integers, decimal numbers, and unary minus.
 *
 * @param {string} expr
 * @returns {string[]}
 */
function tokenize(expr) {
  const tokens = [];
  let i = 0;

  while (i < expr.length) {
    if (expr[i] === ' ') {
      i++;
      continue;
    }

    // number (integer or decimal)
    if (expr[i] >= '0' && expr[i] <= '9') {
      let num = '';
      while (i < expr.length && ((expr[i] >= '0' && expr[i] <= '9') || expr[i] === '.')) {
        num += expr[i++];
      }
      tokens.push(num);
      continue;
    }

    // unary minus: if '-' appears at the start or after '(' or another operator
    if (expr[i] === '-' && (tokens.length === 0 || tokens[tokens.length - 1] === '(' || '+-*/%^'.includes(tokens[tokens.length - 1]))) {
      let num = '-';
      i++;
      while (i < expr.length && ((expr[i] >= '0' && expr[i] <= '9') || expr[i] === '.')) {
        num += expr[i++];
      }
      tokens.push(num);
      continue;
    }

    // operator or parenthesis
    tokens.push(expr[i]);
    i++;
  }

  return tokens;
}

// ---------------------------------------------------------------------------
// Test cases
// ---------------------------------------------------------------------------

function runTests() {
  const tests = [
    // Basic arithmetic
    { input: '3 + 4', expected: '3 4 +' },
    { input: '3 - 4', expected: '3 4 -' },
    { input: '3 * 4', expected: '3 4 *' },
    { input: '3 / 4', expected: '3 4 /' },

    // Operator precedence
    { input: '3 + 4 * 5', expected: '3 4 5 * +' },
    { input: '3 * 4 + 5', expected: '3 4 * 5 +' },
    { input: '1 + 2 + 3', expected: '1 2 + 3 +' },
    { input: '1 * 2 + 3 * 4', expected: '1 2 * 3 4 * +' },
    { input: '1 + 2 * 3 - 4 / 5', expected: '1 2 3 * + 4 5 / -' },

    // Parentheses
    { input: '(3 + 4) * 5', expected: '3 4 + 5 *' },
    { input: '3 * (4 + 5)', expected: '3 4 5 + *' },
    { input: '((1 + 2) * (3 + 4))', expected: '1 2 + 3 4 + *' },
    { input: '(1 + 2) * 3 - (4 - 5)', expected: '1 2 + 3 * 4 5 - -' },

    // Exponentiation (right-associative)
    { input: '2 ^ 3', expected: '2 3 ^' },
    { input: '2 ^ 3 ^ 2', expected: '2 3 2 ^ ^' },
    { input: '(2 ^ 3) ^ 2', expected: '2 3 ^ 2 ^' },

    // Modulo
    { input: '10 % 3', expected: '10 3 %' },
    { input: '10 % 3 + 1', expected: '10 3 % 1 +' },

    // Multi-digit and decimal numbers
    { input: '12 + 34', expected: '12 34 +' },
    { input: '3.5 * 2.1', expected: '3.5 2.1 *' },

    // Unary minus
    { input: '-3 + 4', expected: '-3 4 +' },
    { input: '3 * -4', expected: '3 -4 *' },
    { input: '(-3 + 4) * 2', expected: '-3 4 + 2 *' },

    // Complex expressions
    { input: '3 + 4 * 2 / (1 - 5) ^ 2 ^ 3', expected: '3 4 2 * 1 5 - 2 3 ^ ^ / +' },

    // Single number
    { input: '42', expected: '42' },

    // Nested parentheses
    { input: '(((((1 + 2)))))', expected: '1 2 +' },
  ];

  let passed = 0;
  let failed = 0;

  for (const { input, expected } of tests) {
    const result = lru_cache(input);
    if (result === expected) {
      passed++;
      console.log(`  PASS: "${input}" -> "${result}"`);
    } else {
      failed++;
      console.log(`  FAIL: "${input}"`);
      console.log(`        expected: "${expected}"`);
      console.log(`        got:      "${result}"`);
    }
  }

  console.log(`\n${passed} passed, ${failed} failed out of ${tests.length} tests`);
  return failed === 0;
}

runTests();
